import sys

data = sys.stdin.read().split()
n, m = int(data[0]), int(data[1])
edges = [(int(data[2 + 2 * i]), int(data[3 + 2 * i])) for i in range(m)]

def connected(done, a, b):
    adj = [[] for _ in range(n)]
    for x, y in done:
        adj[x].append(y)
        adj[y].append(x)
    seen = {a}
    stack = [a]
    while stack:
        u = stack.pop()
        for v in adj[u]:
            if v not in seen:
                seen.add(v)
                stack.append(v)
    return b in seen

red = 0
for i in range(m):
    if connected(edges[:i], edges[i][0], edges[i][1]):
        red += 1
label = list(range(n))
changed = True
while changed:
    changed = False
    for x, y in edges:
        lo = min(label[x], label[y])
        if label[x] != lo or label[y] != lo:
            label[x] = label[y] = lo
            changed = True
print(len(set(label)), red)

